-- Data contoh
USE filkompanion;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM volunteer_hours;
DELETE FROM jam_pengabdian;
DELETE FROM issue;
DELETE FROM krs_data;
DELETE FROM ticket;
DELETE FROM volunteer;
DELETE FROM user;
SET FOREIGN_KEY_CHECKS = 1;

SET @senin := DATE_ADD(CURDATE(), INTERVAL (7 - WEEKDAY(CURDATE())) DAY);

-- Data pengguna

-- Data relawan
SET @kunciSinta := CONCAT('{"mingguan":', '{"Senin":["08-10","10-12","15-17"],"Selasa":["10-12","13-15"],"Rabu":["08-10","13-15"],"Kamis":["10-12","15-17"],"Jumat":["08-10"]}', ',"terkunci":[{"tanggal":"', DATE_FORMAT(DATE_ADD(@senin, INTERVAL 2 DAY), '%Y-%m-%d'), '","blok":"13-15","idTiket":"TKT-0138"}]}');

-- Data KRS

-- Data tiket

-- Data laporan kendala

-- Jam per tiket

-- Rekap jam relawan
SELECT j.idRelawan,
       SUM(j.durasiTercatat),
       CASE WHEN SUM(j.statusJam = 'Perlu Ditinjau') > 0 THEN 'Perlu Ditinjau'
            WHEN SUM(j.statusJam = 'Menunggu Verifikasi') > 0 THEN 'Menunggu'
            ELSE 'Terverifikasi' END,
       CASE WHEN SUM(j.statusJam = 'Perlu Ditinjau') > 0 THEN 'Menunggu tindak lanjut laporan kendala LPR-0019.' ELSE NULL END,
       'ADM001',
       '2026-10-19 05:00:00'
FROM jam_pengabdian j
GROUP BY j.idRelawan;

